import{_ as o,o as d,c,a5 as t}from"./chunks/framework.DJo0M80U.js";const _=JSON.parse('{"title":"Filter：过滤器","description":"","frontmatter":{"title":"Filter：过滤器","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","Web基础","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/第四部分：Web 基础/04-Filter 与 Listener/Filter：过滤器.md","filePath":"posts/java快速入门/第四部分：Web 基础/04-Filter 与 Listener/Filter：过滤器.md"}'),l={name:"posts/java快速入门/第四部分：Web 基础/04-Filter 与 Listener/Filter：过滤器.md"};function i(p,e,r,s,a,n){return d(),c("div",null,[...e[0]||(e[0]=[t('<div><p><strong>概念：</strong><code>*</code> 生活中的过滤器：净水器，空气净化器，土匪。 <code>* web</code>中的过滤器：当访问服务器的资源时，过滤器可以将请求拦截下来，完成一些特殊的功能。 <code>*</code> 过滤器的作用： 一般用于完成通用的操作。如：登录验证、统一编码处理、敏感字符过滤<code>...</code></p><p><strong>快速入门步骤</strong>： <code>1.</code> 定义一个类，实现接口</p><ul><li>Filter</li><li><ol start="2"><li></li></ol></li></ul><p>复写方法 <code>3.</code> 配置拦截路径</p><ul><li><ol><li>web.xml</li></ol></li><li><ol start="2"><li></li></ol></li></ul><p>注解</p><p>代码：</p><p><strong>过滤器细节：</strong><code>1. web.xml</code>配置</p><p>&lt;filter&gt; &lt;filter-name&gt;demo1&lt;/filter-name&gt; &lt;filter-class&gt;cn.itcast.web.filter.FilterDemo1&lt;/filter-class&gt; &lt;/filter&gt; &lt;filter-mapping&gt; &lt;filter-name&gt;demo1&lt;/filter-name&gt; &lt;!-- 拦截路径</p><p>--&gt; &lt;url-pattern&gt;/*&lt;/url-pattern&gt; &lt;/filter-mapping&gt;</p><p><code>2.</code> 过滤器执行流程 <code>1.</code> 执行过滤器 <code>2.</code> 执行放行后的资源 <code>3.</code> 回来执行过滤器放行代码下边的代码</p><p><code>3.</code> 过滤器生命周期方法 <code>1. init:</code>在服务器启动后，会创建<code>Filter</code>对象，然后调用<code>init</code>方法。只执行一次。用于加载资源 <code>2. doFilter:</code>每一次请求被拦截资源时，会执行。执行多次 <code>3. destroy:</code>在服务器关闭后，<code>Filter</code>对象被销毁。如果服务器是正常关闭，则会执行<code>destroy</code>方法。只执行一次。用于释放资源</p><p><code>4.</code> 过滤器配置详解 <code>*</code> 拦截路径配置： <code>1.</code> 具体资源路径： <code>/index.jsp</code> 只有访问<code>index.jsp</code>资源时，过滤器才会被执行 <code>2.</code> 拦截目录： <code>/user/*</code> 访问<code>/user</code>下的所有资源时，过滤器都会被执行 <code>3.</code> 后缀名拦截： <code>*.jsp</code> 访问所有后缀名为<code>jsp</code>资源时，过滤器都会被执行 <code>4.</code> 拦截所有资源：<code>/*</code> 访问所有资源时，过滤器都会被执行 <code>*</code> 拦截方式配置：资源被访问的方式 <code>*</code> 注解配置： <code>*</code> 设置<code>dispatcherTypes</code>属性 <code>1. REQUEST</code>：默认值。浏览器直接请求资源 <code>2. FORWARD</code>：转发访问资源 <code>3. INCLUDE</code>：包含访问资源 <code>4. ERROR</code>：错误跳转资源 <code>5. ASYNC</code>：异步访问资源 <code>* web.xml</code>配置 <code>*</code> 设置<code>\\&lt;dispatcher\\&gt;\\&lt;/dispatcher\\&gt;</code>标签即可</p><p><code>5.</code> 过滤器链<code>(</code>配置多个过滤器</p><ul><li>)</li><li><ul><li></li></ul></li></ul><p>执行顺序：如果有两个过滤器：过滤器<code>1</code>和过滤器</p><ul><li>2</li><li><ol><li></li></ol></li></ul><p>过滤器</p><ul><li>1</li><li><ol start="2"><li></li></ol></li></ul><p>过滤器</p><ul><li>2</li><li><ol start="3"><li></li></ol></li></ul><p>资源执行 <code>4.</code> 过滤器</p><ul><li>2</li><li><ol start="5"><li></li></ol></li></ul><p>过滤器<code>1</code></p><p><code>*</code> 过滤器先后顺序问题： <code>1.</code> 注解配置：按照类名的字符串比较规则比较，值小的先执行 <code>*</code> 如： <code>AFilter</code> 和 <code>BFilter</code>，<code>AFilter</code>就先执行了。 <code>2. web.xml</code>配置： <code>\\&lt;filter-mapping\\&gt;</code>谁定义在上边，谁先执行</p><p><strong>案例：</strong><code>1.</code> 案例<code>1_</code>登录验证 <code>*</code> 需求： <code>1.</code> 访问<code>day17_case</code>案例的资源。验证其是否登录 <code>2.</code> 如果登录了，则直接放行。 <code>3.</code> 如果没有登录，则跳转到登录页面，提示<code>&quot;</code>您尚未登录，请先登录<code>&quot;</code>。</p><p><code>2.</code> 案例<code>2_</code>敏感词汇过滤 <code>*</code> 需求： <code>1.</code> 对<code>day17_case</code>案例录入的数据进行敏感词汇过滤 <code>2.</code> 敏感词汇参考《敏感词汇<code>.txt</code>》 <code>3.</code> 如果是敏感词汇，替换为 <code>***</code></p><p><code>*</code> 分析： <code>1.</code> 对<code>request</code>对象进行增强。增强获取参数相关方法 <code>2.</code> 放行。传递代理对象</p><p><code>*</code> 增强对象的功能： <code>*</code> 设计模式：一些通用的解决固定问题的方式 <code>1.</code> 装饰模式 <code>2.</code> 代理模式 <code>*</code> 概念： <code>1.</code> 真实对象：被代理的对象 <code>2.</code> 代理对象： <code>3.</code> 代理模式：代理对象代理真实对象，达到增强真实对象功能的目的 <code>*</code> 实现方式： <code>1.</code> 静态代理：有一个类文件描述代理模式 <code>2.</code> 动态代理：在内存中形成代理类 <code>*</code> 实现步骤： <code>1.</code> 代理对象和真实对象实现相同的接口 <code>2.</code> 代理对象</p><p>= Proxy.newProxyInstance(); 3. 使用代理对象调用方法。 <code>4.</code> 增强方法</p><p><code>*</code> 增强方式： <code>1.</code> 增强参数列表 <code>2.</code> 增强返回值类型 <code>3.</code> 增强方法体执行逻辑</p></div>',1)])])}const u=o(l,[["render",i]]);export{_ as __pageData,u as default};
